// 二维柏林噪声

vec2 hash22(vec2 p)

{

	vec2 v = p.x * vec2(127.1, 269.5) + p.y * vec2(311.7, 183.3);

	vec2 s = sin(v) * 43758.5432123;

	vec2 w = fract(sin(s)) * 2. - 1.;

	w = normalize(w);

	return w;

}

float perlin2(vec2 u)

{

	float d[4];

	vec2 q,p = floor(u);



	for(int i;i<4;i++)

		q = p + vec2(i/2, (i+1)/2%2),                  // q 为 u 所在的四个顶点， p 为最左下角顶点

		d[i]=dot(u-q, hash22(q));                      // 在梯度方向上的投影长

	vec2 m = u - p;                                        // fract(p);   分别表示横纵坐标到原点的距离

	vec2 t = m * m * m * (m * (m * 6. - 15.) + 10.) ;      // 将三角波插值化曲线

	return mix(mix(d[0],d[3],t.x),mix(d[1],d[2],t.x),t.y); // 先混合上下边的端点，再混把上下混合在一起

}
